"use client";
import { useState } from "react";
import { Activity, AlertTriangle, ArrowRight, Bell, Building2, CalendarClock, CalendarDays, CheckCircle2, ClipboardList, Clock3, ContactRound, Handshake, Home, LayoutDashboard, LogOut, Menu, Pencil, Plus, Search, Settings2, Target, Trash2, TrendingUp, Users, X, CircleDollarSign, LockKeyhole } from "lucide-react";
import { useRouter } from "next/navigation";
import { createClient } from "@/lib/supabase/client";
type Lead={id:string;name:string;status:string;stage_id:string|null;created_at:string;source:string|null;lead_type:string|null;estimated_value:number|null;next_follow_up_at:string|null};
type Stage={id:string;name:string;color:string;position:number;is_won:boolean;is_lost:boolean;is_active:boolean};
type Task={id:string;title:string;due_at:string|null;status:string;priority:string;lead_id:string|null};
type Property={id:string;title:string;status:string;listing_price:number|null;currency:string};
type Goal={id:string;metric_key:string;period:string;target_value:number;starts_on:string;ends_on:string|null};
type Act={id:string;activity_type:string;subject:string|null;occurred_at:string;lead_id:string|null};
type StageHistory={id:string;lead_id:string;from_stage_id:string|null;to_stage_id:string|null;changed_at:string};
type CustomField={id:string;name:string;field_key:string;entity_type:string;field_type:string;is_required:boolean;is_active:boolean;options?:unknown};
type Data={leads:Lead[];stages:Stage[];tasks:Task[];properties:Property[];goals:Goal[];activities:Act[];stageHistory:StageHistory[];customFields:CustomField[];dataError:string|null};
const menu=[["overview","Resumen",LayoutDashboard],["leads","Clientes y leads",Users],["pipeline","Pipeline",ContactRound],["tasks","Tareas y seguimiento",CalendarClock],["properties","Propiedades",Building2],["metrics","Métricas",TrendingUp],["settings","Configuración",Settings2]] as const;
type Section=typeof menu[number][0];
const input="w-full rounded-xl border border-slate-200 bg-white px-3.5 py-3 text-sm outline-none focus:border-blue-500 focus:ring-4 focus:ring-blue-50";
const money=(n:number|null|undefined,c="USD")=>{try{return new Intl.NumberFormat("es-BO",{style:"currency",currency:c,maximumFractionDigits:0}).format(n||0)}catch{return String(n||0)}};
const date=(v?:string|null)=>v?new Intl.DateTimeFormat("es-BO",{day:"2-digit",month:"short"}).format(new Date(v)):"Sin fecha";
const today=()=>new Date().toLocaleDateString("en-CA");
const maps:Record<string,Record<string,string>>={type:{buyer:"Comprador",seller:"Vendedor",investor:"Inversor",renter:"Inquilino",owner:"Propietario",other:"Otro"},source:{manual:"Manual",referral:"Referido",social_media:"Redes sociales",portal:"Portal",website:"Web",remax:"RE/MAX",other:"Otro"},status:{available:"Disponible",reserved:"Reservada",sold:"Vendida",rented:"Alquilada",inactive:"Inactiva"},priority:{low:"Baja",normal:"Normal",high:"Alta",urgent:"Urgente"},activity:{call:"Llamada",message:"Mensaje",meeting:"Reunión",property_visit:"Visita",note:"Nota",stage_change:"Cambio de etapa",email:"Correo",task:"Tarea"},metric:{contacts:"Contactos",appointments:"Citas",visits:"Visitas",closings:"Cierres",revenue:"Ingresos"},period:{daily:"Diario",weekly:"Semanal",monthly:"Mensual"}};
const label=(g:string,v:string|null|undefined)=>v?(maps[g]?.[v]||v):"—";
function Field({label,required,children}:{label:string;required?:boolean;children:React.ReactNode}){return <label className="block"><span className="mb-1.5 block text-sm font-medium text-slate-700">{label}{required&&<b className="ml-1 text-rose-500">*</b>}</span>{children}</label>}
function Modal({title,close,children}:{title:string;close:()=>void;children:React.ReactNode}){return <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/40 p-4 backdrop-blur-sm" onMouseDown={e=>{if(e.target===e.currentTarget)close()}}><div className="max-h-[92vh] w-full max-w-2xl overflow-y-auto rounded-2xl bg-white p-5 shadow-2xl sm:p-7"><div className="mb-6 flex items-center justify-between"><h2 className="text-xl font-semibold">{title}</h2><button onClick={close} className="rounded-lg p-2 text-slate-400 hover:bg-slate-100"><X size={20}/></button></div>{children}</div></div>}
function Footer({busy,cancel,children}:{busy:boolean;cancel:()=>void;children:string}){return <div className="flex justify-end gap-3 border-t border-slate-100 pt-4"><button type="button" onClick={cancel} className="rounded-xl border border-slate-200 px-4 py-2.5 text-sm">Cancelar</button><button disabled={busy} className="rounded-xl bg-blue-600 px-5 py-2.5 text-sm font-semibold text-white disabled:opacity-60">{busy?"Guardando…":children}</button></div>}
function Heading({title,sub,action,click}:{title:string;sub:string;action?:string;click?:()=>void}){return <div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><h2 className="text-2xl font-semibold tracking-tight">{title}</h2><p className="mt-2 text-sm text-slate-500">{sub}</p></div>{action&&click&&<button onClick={click} className="inline-flex items-center gap-2 self-start rounded-xl bg-blue-600 px-4 py-3 text-sm font-semibold text-white hover:bg-blue-700"><Plus size={17}/>{action}</button>}</div>}
function Stat({label,value}:{label:string;value:string|number}){return <div className="rounded-2xl border border-slate-200 bg-white p-5"><p className="text-sm text-slate-500">{label}</p><p className="mt-2 text-2xl font-semibold">{value}</p></div>}
function Empty({text}:{text:string}){return <div className="px-5 py-10 text-center"><div className="mx-auto mb-3 flex size-12 items-center justify-center rounded-2xl bg-slate-100 text-slate-400"><ClipboardList size={22}/></div><p className="mx-auto max-w-sm text-sm leading-6 text-slate-500">{text}</p></div>}
export default function Dashboard({profile,initialData}:{profile:{name:string;email:string};initialData:Data}){
 const router=useRouter();const [data,setData]=useState(initialData);const [section,setSection]=useState<Section>("overview");const [navOpen,setNavOpen]=useState(false);const [query,setQuery]=useState("");const [modal,setModal]=useState<"lead"|"task"|"property"|"stage"|null>(null);const [busy,setBusy]=useState(false);const [notice,setNotice]=useState("");const [selected,setSelected]=useState<Lead|null>(null);
 const [lf,setLf]=useState({name:"",phone:"",email:"",lead_type:"buyer",source:"manual",budget_min:"",budget_max:"",notes:"",stage_id:""});const [tf,setTf]=useState({title:"",due_at:"",priority:"normal",lead_id:"",description:""});const [pf,setPf]=useState({title:"",property_type:"apartment",status:"available",listing_price:"",currency:"USD",address:"",neighborhood:""});const [sf,setSf]=useState({name:"",color:"#315efb"});const [gf,setGf]=useState({metric_key:"contacts",period:"daily",target_value:"25",starts_on:today(),ends_on:""});const [customForm,setCustomForm]=useState({entity_type:"lead",name:"",field_key:"",field_type:"text",options:"",is_required:false});const [customFields,setCustomFields]=useState<CustomField[]>(initialData.customFields??[]);const [editingGoalId,setEditingGoalId]=useState<string|null>(null);
 const stages=[...data.stages].sort((a,b)=>a.position-b.position);const filtered=data.leads.filter(l=>l.name.toLowerCase().includes(query.toLowerCase()));const wonIds=new Set(stages.filter(s=>s.is_won).map(s=>s.id));const won=data.leads.filter(l=>l.stage_id&&wonIds.has(l.stage_id));const active=data.leads.filter(l=>!stages.some(s=>s.id===l.stage_id&&(s.is_won||s.is_lost)));const overdue=data.tasks.filter(t=>t.due_at&&new Date(t.due_at)<new Date());const activitiesToday=data.activities.filter(a=>a.occurred_at.slice(0,10)===today()).length;const target=data.goals.find(g=>g.metric_key==="contacts"&&g.starts_on<=today()&&(!g.ends_on||g.ends_on>=today()))?.target_value??25;const currentTitle=menu.find(m=>m[0]===section)?.[1]||"Resumen";
 async function refresh(){const sb=createClient();const [l,s,t,p,g,a,h,cf]=await Promise.all([sb.from("leads").select("id,name,status,stage_id,created_at,source,lead_type,estimated_value,next_follow_up_at").order("created_at",{ascending:false}).limit(500),sb.from("pipeline_stages").select("id,name,color,position,is_won,is_lost,is_active").eq("is_active",true).order("position"),sb.from("tasks").select("id,title,due_at,status,priority,lead_id").neq("status","completed").order("due_at").limit(100),sb.from("properties").select("id,title,status,listing_price,currency").order("created_at",{ascending:false}).limit(100),sb.from("goals").select("id,metric_key,period,target_value,starts_on,ends_on").order("starts_on",{ascending:false}).limit(100),sb.from("activities").select("id,activity_type,subject,occurred_at,lead_id").order("occurred_at",{ascending:false}).limit(1000),sb.from("stage_history").select("id,lead_id,from_stage_id,to_stage_id,changed_at").order("changed_at",{ascending:false}).limit(2000),sb.from("custom_fields").select("id,name,field_key,entity_type,field_type,is_required,is_active").eq("is_active",true).order("position")]);setCustomFields(cf.data??[]);setData({leads:l.data??[],stages:s.data??[],tasks:t.data??[],properties:p.data??[],goals:g.data??[],activities:a.data??[],stageHistory:h.data??[],customFields:cf.data??[],dataError:[l.error,s.error,t.error,p.error,g.error,a.error,h.error].some(Boolean)?"Error de datos. Verificá migración y RLS.":null});}
 async function signOut(){const sb=createClient();await sb.auth.signOut();router.replace("/login");router.refresh()}
 async function saveLead(e:React.FormEvent<HTMLFormElement>){e.preventDefault();setBusy(true);const sb=createClient();const {data:r,error}=await sb.from("leads").insert({name:lf.name.trim(),phone:lf.phone||null,email:lf.email||null,lead_type:lf.lead_type,source:lf.source,budget_min:lf.budget_min?Number(lf.budget_min):null,budget_max:lf.budget_max?Number(lf.budget_max):null,notes:lf.notes||null,stage_id:lf.stage_id||stages[0]?.id||null}).select("id").single();if(error){setNotice(error.message);setBusy(false);return}if(r)await sb.from("activities").insert({lead_id:r.id,activity_type:"note",subject:"Lead creado",notes:"Cliente agregado al CRM"});setModal(null);await refresh();setBusy(false)}
 async function moveLead(lead:Lead,id:string){const old=stages.find(s=>s.id===lead.stage_id),next=stages.find(s=>s.id===id);if(!next||next.id===lead.stage_id)return;const sb=createClient();const {error}=await sb.from("leads").update({stage_id:id,status:next.is_won?"won":next.is_lost?"lost":"active",updated_at:new Date().toISOString()}).eq("id",lead.id);if(error){setNotice(error.message);return}await sb.from("stage_history").insert({lead_id:lead.id,from_stage_id:old?.id??null,to_stage_id:next.id,changed_at:new Date().toISOString()});await sb.from("activities").insert({lead_id:lead.id,activity_type:"stage_change",subject:"Cambio de etapa",notes:(old?.name||"Sin etapa")+" → "+next.name});await refresh()}
 async function saveTask(e:React.FormEvent<HTMLFormElement>){e.preventDefault();setBusy(true);const sb=createClient();const {error}=await sb.from("tasks").insert({title:tf.title.trim(),due_at:tf.due_at||null,priority:tf.priority,lead_id:tf.lead_id||null,description:tf.description||null});if(error){setNotice(error.message);setBusy(false);return}setModal(null);await refresh();setBusy(false)}
 async function finishTask(id:string){const sb=createClient();const {error}=await sb.from("tasks").update({status:"completed",completed_at:new Date().toISOString()}).eq("id",id);if(error)setNotice(error.message);else await refresh()}
 async function saveProperty(e:React.FormEvent<HTMLFormElement>){e.preventDefault();setBusy(true);const sb=createClient();const {error}=await sb.from("properties").insert({title:pf.title.trim(),property_type:pf.property_type,status:pf.status,listing_price:pf.listing_price?Number(pf.listing_price):null,currency:pf.currency,address:pf.address||null,neighborhood:pf.neighborhood||null});if(error){setNotice(error.message);setBusy(false);return}setModal(null);await refresh();setBusy(false)}
 async function saveStage(e:React.FormEvent<HTMLFormElement>){e.preventDefault();setBusy(true);const sb=createClient();const {error}=await sb.from("pipeline_stages").insert({name:sf.name.trim(),color:sf.color,position:stages.length+1});if(error){setNotice(error.message);setBusy(false);return}setModal(null);await refresh();setBusy(false)}
 async function createField(e:React.FormEvent<HTMLFormElement>){e.preventDefault();setBusy(true);const sb=createClient();const {error}=await sb.from("custom_fields").insert({entity_type:customForm.entity_type,name:customForm.name.trim(),field_key:customForm.field_key,field_type:customForm.field_type,options:customForm.field_type==="select"?customForm.options.split(",").map(x=>x.trim()).filter(Boolean):[],is_required:customForm.is_required,position:customFields.length});if(error)setNotice(error.message);else{setNotice("Campo personalizado creado.");setCustomForm({entity_type:"lead",name:"",field_key:"",field_type:"text",options:"",is_required:false});await refresh()}setBusy(false)}
 async function saveGoal(e:React.FormEvent<HTMLFormElement>){e.preventDefault();setBusy(true);const sb=createClient();const payload={metric_key:gf.metric_key,period:gf.period,target_value:Number(gf.target_value),starts_on:gf.starts_on,ends_on:gf.ends_on||null,updated_at:new Date().toISOString()};const result=editingGoalId?await sb.from("goals").update(payload).eq("id",editingGoalId):await sb.from("goals").insert(payload);if(result.error)setNotice(result.error.message);else{setNotice(editingGoalId?"Objetivo actualizado.":"Objetivo guardado.");setEditingGoalId(null);setGf({metric_key:"contacts",period:"daily",target_value:"25",starts_on:today(),ends_on:""});await refresh()}setBusy(false)}
  async function deleteGoal(id:string){if(!window.confirm("¿Eliminar este objetivo? Esta acción no se puede deshacer."))return;const sb=createClient();const {error}=await sb.from("goals").delete().eq("id",id);if(error)setNotice(error.message);else{if(editingGoalId===id){setEditingGoalId(null);setGf({metric_key:"contacts",period:"daily",target_value:"25",starts_on:today(),ends_on:""})}setNotice("Objetivo eliminado.");await refresh()}}
 async function removeLead(l:Lead){if(!window.confirm("¿Eliminar a "+l.name+"?"))return;const sb=createClient();const {error}=await sb.from("leads").delete().eq("id",l.id);if(error)setNotice(error.message);else{setSelected(null);await refresh()}}
 return <div className="min-h-screen"><aside className={`fixed inset-y-0 left-0 z-40 flex w-[260px] flex-col bg-[#101c36] text-white transition-transform lg:translate-x-0 ${navOpen?"translate-x-0":"-translate-x-full"}`}><div className="flex h-[82px] items-center gap-3 border-b border-white/10 px-6"><div className="rounded-xl bg-blue-500 p-2.5"><Building2 size={22}/></div><div><p className="font-semibold tracking-wide">ASESOR CRM</p><p className="text-xs text-white/50">Real Estate Workspace</p></div><button onClick={()=>setNavOpen(false)} className="ml-auto lg:hidden"><X/></button></div><p className="px-5 pb-2 pt-6 text-[10px] font-semibold uppercase tracking-[.18em] text-white/35">Workspace</p><nav className="space-y-1 px-3">{menu.map(([id,name,Icon])=><button key={id} onClick={()=>{setSection(id);setNavOpen(false);setNotice("")}} className={`flex w-full items-center gap-3 rounded-xl px-3.5 py-3 text-left text-[13px] font-medium ${section===id?"bg-blue-600 text-white":"text-white/65 hover:bg-white/5 hover:text-white"}`}><Icon size={18}/>{name}{id==="tasks"&&overdue.length>0&&<span className="ml-auto rounded-md bg-rose-500 px-2 py-0.5 text-[10px]">{overdue.length}</span>}</button>)}</nav><div className="mt-auto p-4"><div className="rounded-2xl border border-white/10 bg-white/5 p-4"><div className="mb-2 flex items-center gap-2 text-blue-300"><Target size={16}/><span className="text-xs font-semibold">Objetivo diario</span></div><div className="text-2xl font-semibold">{activitiesToday}<span className="text-sm font-normal text-white/50"> / {target}</span></div><div className="mt-3 h-1.5 overflow-hidden rounded-full bg-white/10"><div className="h-full rounded-full bg-blue-400" style={{width:`${Math.min(100,activitiesToday/Math.max(1,target)*100)}%`}}/></div><p className="mt-2 text-[11px] text-white/40">Actividades registradas</p></div><button onClick={signOut} className="mt-4 flex w-full items-center gap-3 rounded-xl px-3 py-3 text-sm text-white/55"><LogOut size={17}/>Cerrar sesión</button></div></aside>{navOpen&&<button aria-label="Cerrar menú" onClick={()=>setNavOpen(false)} className="fixed inset-0 z-30 bg-slate-950/40 lg:hidden"/>}
 <div className="min-h-screen lg:pl-[260px]"><header className="sticky top-0 z-20 flex h-[76px] items-center justify-between border-b border-slate-200/80 bg-white/90 px-5 backdrop-blur-xl sm:px-8"><div className="flex items-center gap-3"><button onClick={()=>setNavOpen(true)} className="rounded-lg p-2 text-slate-600 lg:hidden"><Menu/></button><div><p className="text-[11px] font-medium uppercase tracking-wider text-slate-400">CRM / {currentTitle}</p><h1 className="mt-0.5 text-lg font-semibold">{currentTitle}</h1></div></div><div className="flex items-center gap-3"><button onClick={()=>setModal("task")} className="relative rounded-xl border border-slate-200 p-2.5 text-slate-600"><Bell size={18}/>{overdue.length>0&&<span className="absolute right-1 top-1 size-2 rounded-full bg-rose-500"/>}</button><div className="hidden text-right sm:block"><p className="text-sm font-semibold">{profile.name}</p><p className="text-xs text-slate-400">Agente inmobiliario</p></div><div className="flex size-10 items-center justify-center rounded-full bg-blue-100 text-sm font-bold text-blue-700">{profile.name.split(" ").map(w=>w[0]).slice(0,2).join("").toUpperCase()}</div></div></header>
 <main className="mx-auto max-w-[1600px] p-5 sm:p-8">{notice&&<div className="mb-5 flex items-start gap-2 rounded-xl border border-blue-100 bg-blue-50 px-4 py-3 text-sm text-blue-800"><span className="flex-1">{notice}</span><button onClick={()=>setNotice("")}><X size={16}/></button></div>}{data.dataError&&<div className="mb-5 rounded-xl border border-amber-200 bg-amber-50 px-4 py-3 text-sm text-amber-800">{data.dataError}</div>}{section==="overview"&&<Overview data={data} active={active.length} won={won.length} target={target} count={activitiesToday} go={setSection} action={setModal}/>}{section==="leads"&&<Leads data={filtered} stages={stages} query={query} setQuery={setQuery} add={()=>setModal("lead")} open={setSelected}/>}{section==="pipeline"&&<Pipeline leads={data.leads} stages={stages} move={moveLead} open={setSelected} add={()=>setModal("lead")} addStage={()=>setModal("stage")}/>}{section==="tasks"&&<Tasks tasks={data.tasks} leads={data.leads} add={()=>setModal("task")} finish={finishTask}/>}{section==="properties"&&<Properties items={data.properties} add={()=>setModal("property")}/>}{section==="metrics"&&<Metrics data={data} active={active.length} won={won.length} form={gf} setForm={setGf} save={saveGoal} busy={busy} editingGoalId={editingGoalId} editGoal={(g)=>{setEditingGoalId(g.id);setGf({metric_key:g.metric_key,period:g.period,target_value:String(g.target_value),starts_on:g.starts_on,ends_on:g.ends_on||""});window.scrollTo({top:0,behavior:"smooth"})}} deleteGoal={deleteGoal} cancelEdit={()=>{setEditingGoalId(null);setGf({metric_key:"contacts",period:"daily",target_value:"25",starts_on:today(),ends_on:""})}}/>}{section==="settings"&&<Settings stages={stages} add={()=>setModal("stage")} reload={refresh} email={profile.email} fields={customFields} customForm={customForm} setCustomForm={setCustomForm} createField={createField} busy={busy}/>}</main></div>
 {selected&&<LeadPanel lead={selected} stages={stages} close={()=>setSelected(null)} move={moveLead} remove={removeLead} refresh={refresh} notice={setNotice}/>}
 {modal&&<Modal title={modal==="lead"?"Nuevo cliente":modal==="task"?"Nueva tarea":modal==="property"?"Nueva propiedad":"Nueva etapa del pipeline"} close={()=>setModal(null)}>{modal==="lead"&&<form onSubmit={saveLead} className="space-y-4"><Field label="Nombre completo" required><input autoFocus required className={input} value={lf.name} onChange={e=>setLf({...lf,name:e.target.value})} placeholder="Ej. María Fernández"/></Field><div className="grid gap-4 sm:grid-cols-2"><Field label="Teléfono"><input className={input} value={lf.phone} onChange={e=>setLf({...lf,phone:e.target.value})} placeholder="+591..."/></Field><Field label="Correo"><input type="email" className={input} value={lf.email} onChange={e=>setLf({...lf,email:e.target.value})} placeholder="correo@ejemplo.com"/></Field></div><div className="grid gap-4 sm:grid-cols-2"><Field label="Tipo"><select className={input} value={lf.lead_type} onChange={e=>setLf({...lf,lead_type:e.target.value})}><option value="buyer">Comprador</option><option value="seller">Vendedor</option><option value="investor">Inversor</option><option value="renter">Inquilino</option><option value="owner">Propietario</option><option value="other">Otro</option></select></Field><Field label="Origen"><select className={input} value={lf.source} onChange={e=>setLf({...lf,source:e.target.value})}><option value="manual">Manual</option><option value="referral">Referido</option><option value="social_media">Redes sociales</option><option value="portal">Portal</option><option value="website">Web</option><option value="remax">RE/MAX</option><option value="other">Otro</option></select></Field></div><div className="grid gap-4 sm:grid-cols-2"><Field label="Presupuesto mínimo"><input type="number" min="0" className={input} value={lf.budget_min} onChange={e=>setLf({...lf,budget_min:e.target.value})}/></Field><Field label="Presupuesto máximo"><input type="number" min="0" className={input} value={lf.budget_max} onChange={e=>setLf({...lf,budget_max:e.target.value})}/></Field></div><Field label="Etapa inicial"><select className={input} value={lf.stage_id} onChange={e=>setLf({...lf,stage_id:e.target.value})}><option value="">Primera etapa</option>{stages.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select></Field><Field label="Notas iniciales"><textarea rows={3} className={input} value={lf.notes} onChange={e=>setLf({...lf,notes:e.target.value})} placeholder="Necesidades y próximo paso…"/></Field><Footer busy={busy} cancel={()=>setModal(null)}>Guardar cliente</Footer></form>}{modal==="task"&&<form onSubmit={saveTask} className="space-y-4"><Field label="Título" required><input required autoFocus className={input} value={tf.title} onChange={e=>setTf({...tf,title:e.target.value})} placeholder="Llamar para coordinar visita"/></Field><div className="grid gap-4 sm:grid-cols-2"><Field label="Fecha y hora"><input type="datetime-local" className={input} value={tf.due_at} onChange={e=>setTf({...tf,due_at:e.target.value})}/></Field><Field label="Prioridad"><select className={input} value={tf.priority} onChange={e=>setTf({...tf,priority:e.target.value})}><option value="low">Baja</option><option value="normal">Normal</option><option value="high">Alta</option><option value="urgent">Urgente</option></select></Field></div><Field label="Cliente"><select className={input} value={tf.lead_id} onChange={e=>setTf({...tf,lead_id:e.target.value})}><option value="">Sin vincular</option>{data.leads.map(l=><option key={l.id} value={l.id}>{l.name}</option>)}</select></Field><Field label="Descripción"><textarea rows={3} className={input} value={tf.description} onChange={e=>setTf({...tf,description:e.target.value})}/></Field><Footer busy={busy} cancel={()=>setModal(null)}>Crear tarea</Footer></form>}{modal==="property"&&<form onSubmit={saveProperty} className="space-y-4"><Field label="Título" required><input required autoFocus className={input} value={pf.title} onChange={e=>setPf({...pf,title:e.target.value})}/></Field><div className="grid gap-4 sm:grid-cols-2"><Field label="Tipo"><select className={input} value={pf.property_type} onChange={e=>setPf({...pf,property_type:e.target.value})}><option value="house">Casa</option><option value="apartment">Departamento</option><option value="land">Terreno</option><option value="commercial">Comercial</option><option value="office">Oficina</option><option value="other">Otro</option></select></Field><Field label="Estado"><select className={input} value={pf.status} onChange={e=>setPf({...pf,status:e.target.value})}><option value="available">Disponible</option><option value="reserved">Reservada</option><option value="sold">Vendida</option><option value="rented">Alquilada</option><option value="inactive">Inactiva</option></select></Field></div><div className="grid gap-4 sm:grid-cols-2"><Field label="Precio"><input type="number" min="0" className={input} value={pf.listing_price} onChange={e=>setPf({...pf,listing_price:e.target.value})}/></Field><Field label="Moneda"><select className={input} value={pf.currency} onChange={e=>setPf({...pf,currency:e.target.value})}><option value="USD">USD</option><option value="BOB">BOB</option><option value="ARS">ARS</option></select></Field></div><Field label="Dirección"><input className={input} value={pf.address} onChange={e=>setPf({...pf,address:e.target.value})}/></Field><Field label="Zona / barrio"><input className={input} value={pf.neighborhood} onChange={e=>setPf({...pf,neighborhood:e.target.value})}/></Field><Footer busy={busy} cancel={()=>setModal(null)}>Guardar propiedad</Footer></form>}{modal==="stage"&&<form onSubmit={saveStage} className="space-y-4"><Field label="Nombre de etapa" required><input required autoFocus className={input} value={sf.name} onChange={e=>setSf({...sf,name:e.target.value})}/></Field><Field label="Color"><input type="color" className="h-12 w-full rounded-xl border border-slate-200 bg-white p-1" value={sf.color} onChange={e=>setSf({...sf,color:e.target.value})}/></Field><Footer busy={busy} cancel={()=>setModal(null)}>Crear etapa</Footer></form>}</Modal>}</div>;
}
function Overview({data,active,won,target,count,go,action}:{data:Data;active:number;won:number;target:number;count:number;go:(s:Section)=>void;action:(m:"lead"|"task"|"property"|"stage"|null)=>void}){
 const newToday=data.leads.filter(l=>l.created_at.slice(0,10)===today()).length;const overdue=data.tasks.filter(t=>t.due_at&&new Date(t.due_at)<new Date()).length;const value=data.leads.filter(l=>l.status!=="won"&&l.status!=="lost").reduce((n,l)=>n+(l.estimated_value||0),0);const cards=[{name:"Leads activos",value:active,sub:"En proceso comercial",icon:Users,tone:"bg-blue-50 text-blue-600",trend:"+"+newToday+" hoy"},{name:"Cierres logrados",value:won,sub:"Operaciones ganadas",icon:Handshake,tone:"bg-emerald-50 text-emerald-600",trend:"Histórico"},{name:"Tareas pendientes",value:data.tasks.length,sub:overdue?overdue+" vencidas":"Por completar",icon:CalendarClock,tone:"bg-amber-50 text-amber-600",trend:overdue?"Atención":"Al día"},{name:"Valor estimado",value:money(value),sub:"Pipeline en seguimiento",icon:CircleDollarSign,tone:"bg-violet-50 text-violet-600",trend:"Oportunidades"}];
 return <div className="space-y-7"><div className="flex flex-col justify-between gap-4 md:flex-row md:items-end"><div><p className="mb-2 text-sm capitalize text-slate-500">{new Intl.DateTimeFormat("es-BO",{weekday:"long",day:"numeric",month:"long"}).format(new Date())}</p><h2 className="text-2xl font-semibold tracking-tight sm:text-3xl">Tus resultados, en perspectiva.</h2><p className="mt-2 text-sm text-slate-500">Prioridades claras y seguimiento constante.</p></div><button onClick={()=>action("lead")} className="inline-flex items-center gap-2 self-start rounded-xl bg-blue-600 px-4 py-3 text-sm font-semibold text-white"><Plus size={17}/>Nuevo cliente</button></div><div className="grid gap-4 sm:grid-cols-2 2xl:grid-cols-4">{cards.map(c=>{const I=c.icon;return <div key={c.name} className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><div className="flex items-start justify-between"><div className={`${c.tone} rounded-xl p-2.5`}><I size={19}/></div><span className="text-[11px] text-slate-400">{c.trend}</span></div><p className="mt-5 text-sm text-slate-500">{c.name}</p><p className="mt-1 text-2xl font-semibold">{c.value}</p><p className="mt-1 text-xs text-slate-400">{c.sub}</p></div>})}</div><div className="grid gap-5 xl:grid-cols-[1.5fr_1fr]"><section className="rounded-2xl border border-slate-200 bg-white p-5 sm:p-6"><div className="flex items-start justify-between"><div><h3 className="font-semibold">Actividad comercial</h3><p className="mt-1 text-xs text-slate-500">Actividad registrada hoy frente al objetivo</p></div><button onClick={()=>go("metrics")} className="text-xs font-semibold text-blue-600">Ver métricas <ArrowRight size={13} className="ml-1 inline"/></button></div><div className="mt-7 flex items-end gap-3"><span className="text-4xl font-semibold">{count}</span><span className="mb-1 text-sm text-slate-400">de {target} actividades</span></div><div className="mt-4 h-2 overflow-hidden rounded-full bg-slate-100"><div className="h-full rounded-full bg-blue-600" style={{width:`${Math.min(100,count/Math.max(1,target)*100)}%`}}/></div><div className="mt-3 flex justify-between text-xs text-slate-500"><span>{Math.round(count/Math.max(1,target)*100)}% del objetivo</span><span>{Math.max(0,target-count)} restantes</span></div></section><section className="rounded-2xl border border-slate-200 bg-white p-5 sm:p-6"><h3 className="font-semibold">Accesos rápidos</h3><div className="mt-5 space-y-2">{[{name:"Agregar contacto",icon:Users,action:()=>action("lead")},{name:"Programar seguimiento",icon:CalendarClock,action:()=>action("task")},{name:"Cargar propiedad",icon:Home,action:()=>action("property")},{name:"Revisar pipeline",icon:ContactRound,action:()=>go("pipeline")}].map(x=>{const I=x.icon;return <button key={x.name} onClick={x.action} className="group flex w-full items-center gap-3 rounded-xl p-3 text-left hover:bg-slate-50"><div className="rounded-xl border border-slate-200 p-2.5 text-slate-600 group-hover:bg-blue-50 group-hover:text-blue-600"><I size={17}/></div><span className="flex-1 text-sm font-medium">{x.name}</span><ArrowRight size={16} className="text-slate-300"/></button>})}</div></section></div><div className="grid gap-5 xl:grid-cols-[1.35fr_1fr]"><section className="rounded-2xl border border-slate-200 bg-white p-5"><h3 className="mb-5 font-semibold">Pipeline por etapa</h3><div className="space-y-4">{data.stages.slice(0,7).map(s=>{const n=data.leads.filter(l=>l.stage_id===s.id).length;const max=Math.max(1,...data.stages.map(z=>data.leads.filter(l=>l.stage_id===z.id).length));return <div key={s.id}><div className="mb-2 flex items-center justify-between text-sm"><span className="flex items-center gap-2 text-slate-600"><span className="size-2 rounded-full" style={{background:s.color}}/>{s.name}</span><span className="font-semibold">{n}</span></div><div className="h-2 overflow-hidden rounded-full bg-slate-100"><div className="h-full rounded-full" style={{width:`${n/max*100}%`,background:s.color}}/></div></div>})}{!data.stages.length&&<Empty text="Ejecutá la migración SQL para crear las etapas."/>}</div></section><section className="rounded-2xl border border-slate-200 bg-white p-5"><h3 className="mb-5 font-semibold">Actividad reciente</h3>{data.activities.slice(0,6).map(a=><div key={a.id} className="flex gap-3 py-2"><Activity size={16} className="mt-1 text-blue-600"/><div><p className="text-sm font-medium">{a.subject||label("activity",a.activity_type)}</p><p className="text-xs text-slate-400">{date(a.occurred_at)}</p></div></div>)}{!data.activities.length&&<Empty text="Las notas y cambios aparecerán aquí."/>}</section></div></div>;
}
function Leads({data,stages,query,setQuery,add,open}:{data:Lead[];stages:Stage[];query:string;setQuery:(s:string)=>void;add:()=>void;open:(l:Lead)=>void}){return <div className="space-y-5"><Heading title="Clientes y leads" sub="Tu cartera de contactos en un solo lugar." action="Nuevo cliente" click={add}/><div className="rounded-2xl border border-slate-200 bg-white"><div className="flex items-center gap-3 border-b border-slate-100 p-4"><div className="relative max-w-md flex-1"><Search size={17} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Buscar por nombre…" className="w-full rounded-xl border border-slate-200 py-2.5 pl-10 pr-3 text-sm"/></div><span className="text-xs text-slate-500">{data.length} registros</span></div><div className="overflow-x-auto"><table className="w-full min-w-[760px] text-left text-sm"><thead className="bg-slate-50 text-xs uppercase tracking-wider text-slate-400"><tr>{["Cliente","Tipo","Origen","Etapa","Seguimiento","Valor"].map(x=><th key={x} className="px-5 py-3.5 font-medium">{x}</th>)}</tr></thead><tbody className="divide-y divide-slate-100">{data.map(l=><tr key={l.id} className="hover:bg-slate-50"><td className="px-5 py-4"><button onClick={()=>open(l)} className="font-semibold hover:text-blue-600">{l.name}</button><p className="mt-1 text-xs text-slate-400">Alta {date(l.created_at)}</p></td><td className="px-5 py-4 text-slate-500">{label("type",l.lead_type)}</td><td className="px-5 py-4 text-slate-500">{label("source",l.source)}</td><td className="px-5 py-4">{stages.find(s=>s.id===l.stage_id)?.name||"—"}</td><td className="px-5 py-4 text-slate-500">{date(l.next_follow_up_at)}</td><td className="px-5 py-4">{l.estimated_value?money(l.estimated_value):"—"}</td></tr>)}</tbody></table>{!data.length&&<Empty text="Todavía no hay clientes. Agregá tu primer lead."/>}</div></div></div>}
function Pipeline({leads,stages,move,open,add,addStage}:{leads:Lead[];stages:Stage[];move:(l:Lead,id:string)=>void;open:(l:Lead)=>void;add:()=>void;addStage:()=>void}){const [drag,setDrag]=useState<string|null>(null);return <div className="space-y-5"><Heading title="Pipeline comercial" sub="Mové cada oportunidad a medida que avances." action="Nuevo lead" click={add}/><div className="flex items-center justify-between gap-3"><p className="text-xs text-slate-500">Arrastrá tarjetas o cambiá su etapa.</p><button onClick={addStage} className="inline-flex items-center gap-2 rounded-xl border bg-white px-3.5 py-2.5 text-sm"><Plus size={16}/>Nueva etapa</button></div><div className="flex gap-4 overflow-x-auto pb-4">{stages.map(s=>{const items=leads.filter(l=>l.stage_id===s.id);return <div key={s.id} onDragOver={e=>e.preventDefault()} onDrop={e=>{e.preventDefault();const l=leads.find(x=>x.id===drag);if(l)move(l,s.id);setDrag(null)}} className="w-[285px] min-w-[285px] rounded-2xl border border-slate-200 bg-slate-100/80 p-3"><div className="mb-4 flex items-center justify-between px-1"><span className="flex items-center gap-2 text-sm font-semibold"><span className="size-2.5 rounded-full" style={{background:s.color}}/>{s.name}</span><span className="rounded-lg bg-white px-2 py-1 text-xs">{items.length}</span></div><div className="space-y-3">{items.map(l=><article key={l.id} draggable onDragStart={()=>setDrag(l.id)} className="cursor-grab rounded-xl border border-slate-200 bg-white p-4 shadow-sm"><button onClick={()=>open(l)} className="text-left text-sm font-semibold hover:text-blue-600">{l.name}</button><p className="mt-1.5 text-xs text-slate-500">{label("type",l.lead_type)} · {label("source",l.source)}</p><div className="mt-3 flex items-center justify-between border-t border-slate-100 pt-3"><span className="text-[11px] text-slate-400">{date(l.next_follow_up_at)}</span><select aria-label={"Mover "+l.name} value={l.stage_id||""} onChange={e=>move(l,e.target.value)} className="max-w-28 rounded-lg bg-slate-50 px-2 py-1.5 text-[11px]"><option value="">Mover a…</option>{stages.filter(x=>x.id!==s.id).map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></div></article>)}{!items.length&&<div className="rounded-xl border border-dashed border-slate-300 px-3 py-8 text-center text-xs text-slate-400">Soltá un lead aquí</div>}</div></div>})}{!stages.length&&<Empty text="Ejecutá la migración SQL para crear las etapas."/>}</div></div>}
function Tasks({tasks,leads,add,finish}:{tasks:Task[];leads:Lead[];add:()=>void;finish:(id:string)=>void}){return <div className="space-y-5"><Heading title="Tareas y seguimiento" sub="No dejes que una oportunidad se enfríe." action="Nueva tarea" click={add}/><div className="grid gap-4 sm:grid-cols-3"><Stat label="Pendientes" value={tasks.length}/><Stat label="Vencidas" value={tasks.filter(t=>t.due_at&&new Date(t.due_at)<new Date()).length}/><Stat label="Prioridad alta" value={tasks.filter(t=>t.priority==="high"||t.priority==="urgent").length}/></div><div className="rounded-2xl border border-slate-200 bg-white p-2 sm:p-4">{tasks.map(t=><div key={t.id} className="flex items-start gap-3 rounded-xl p-3 hover:bg-slate-50 sm:p-4"><button onClick={()=>finish(t.id)} aria-label="Completar tarea" className="mt-1 text-slate-300 hover:text-emerald-600"><CheckCircle2 size={21}/></button><div className="min-w-0 flex-1"><p className="font-medium">{t.title}</p><p className="mt-1 text-xs text-slate-500">{t.lead_id?leads.find(l=>l.id===t.lead_id)?.name||"Cliente":"Tarea general"} · {date(t.due_at)}</p></div><span className="rounded-full bg-slate-100 px-2.5 py-1 text-[10px] font-semibold">{t.due_at&&new Date(t.due_at)<new Date()?"Vencida":label("priority",t.priority)}</span></div>)}{!tasks.length&&<Empty text="No tenés tareas pendientes. Programá el próximo seguimiento."/>}</div></div>}
function Properties({items,add}:{items:Property[];add:()=>void}){return <div className="space-y-5"><Heading title="Propiedades" sub="Inventario y oportunidades de tu cartera." action="Nueva propiedad" click={add}/><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{items.map(p=><div key={p.id} className="overflow-hidden rounded-2xl border border-slate-200 bg-white"><div className="flex h-32 items-center justify-center bg-gradient-to-br from-slate-100 to-blue-50 text-blue-200"><Building2 size={42}/></div><div className="p-5"><div className="flex items-start justify-between gap-3"><h3 className="font-semibold">{p.title}</h3><span className="rounded-full bg-emerald-50 px-2.5 py-1 text-[10px] font-semibold text-emerald-700">{label("status",p.status)}</span></div><p className="mt-3 text-xl font-semibold">{p.listing_price?money(p.listing_price,p.currency):"Consultar precio"}</p></div></div>)}{!items.length&&<div className="col-span-full rounded-2xl border border-slate-200 bg-white p-10"><Empty text="Todavía no registraste propiedades."/></div>}</div></div>}
function Metrics({data,active,won,form,setForm,save,busy,editingGoalId,editGoal,deleteGoal,cancelEdit}:{data:Data;active:number;won:number;form:{metric_key:string;period:string;target_value:string;starts_on:string;ends_on:string};setForm:(v:typeof form)=>void;save:(e:React.FormEvent<HTMLFormElement>)=>void;busy:boolean;editingGoalId:string|null;editGoal:(g:Goal)=>void;deleteGoal:(id:string)=>void;cancelEdit:()=>void}){
 const stageById=new Map(data.stages.map(s=>[s.id,s]));
 const isWonLead=(l:Lead)=>Boolean(l.stage_id&&stageById.get(l.stage_id)?.is_won)||l.status==="won";
 const isLostLead=(l:Lead)=>Boolean(l.stage_id&&stageById.get(l.stage_id)?.is_lost)||l.status==="lost";
 const stageHistoryFor=(keywords:string[])=>data.stageHistory.filter(h=>keywords.some(k=>(stageById.get(h.to_stage_id||"")?.name||"").toLowerCase().includes(k)));
 const idsFromHistory=(items:StageHistory[])=>new Set(items.map(h=>h.lead_id));
 const appointmentIds=new Set(data.activities.filter(a=>a.activity_type==="meeting"&&a.lead_id).map(a=>a.lead_id as string));
 stageHistoryFor(["cita","appointment"]).forEach(h=>appointmentIds.add(h.lead_id));
 const visitIds=new Set(data.activities.filter(a=>a.activity_type==="property_visit"&&a.lead_id).map(a=>a.lead_id as string));
 stageHistoryFor(["visita","visit"]).forEach(h=>visitIds.add(h.lead_id));
 const negotiationIds=idsFromHistory(stageHistoryFor(["negoci"]));
 data.leads.filter(l=>l.stage_id&&(stageById.get(l.stage_id)?.name||"").toLowerCase().includes("negoci")).forEach(l=>negotiationIds.add(l.id));
 const wonLeads=data.leads.filter(isWonLead);
 const closedHistory=data.stageHistory.filter(h=>Boolean(h.to_stage_id&&stageById.get(h.to_stage_id)?.is_won));
 const funnel=[{name:"Contactos",count:data.leads.length,color:"#64748b"},{name:"Citas",count:appointmentIds.size,color:"#3b82f6"},{name:"Visitas",count:visitIds.size,color:"#8b5cf6"},{name:"Negociaciones",count:negotiationIds.size,color:"#d97706"},{name:"Cierres",count:wonLeads.length,color:"#16a34a"}];
 const noFollowUp=data.leads.filter(l=>!isWonLead(l)&&!isLostLead(l)&&(!l.next_follow_up_at||new Date(l.next_follow_up_at)<new Date()));
 const closeDurations=wonLeads.map(l=>{const h=closedHistory.filter(x=>x.lead_id===l.id).sort((a,b)=>new Date(b.changed_at).getTime()-new Date(a.changed_at).getTime())[0];return h?Math.max(0,(new Date(h.changed_at).getTime()-new Date(l.created_at).getTime())/86400000):null}).filter((n):n is number=>n!==null);
 const averageCloseDays=closeDurations.length?Math.round(closeDurations.reduce((a,b)=>a+b,0)/closeDurations.length):null;
 const sources=[...new Set(data.leads.map(l=>l.source||"other"))].map(source=>{const ls=data.leads.filter(l=>(l.source||"other")===source);const wins=ls.filter(isWonLead).length;return {source,label:label("source",source),total:ls.length,wins,rate:ls.length?Math.round(wins/ls.length*100):0}}).sort((a,b)=>b.total-a.total);
 const goalActual=(g:Goal)=>{const start=g.starts_on;const end=g.ends_on||today();const inRange=(v:string|null|undefined)=>Boolean(v&&v.slice(0,10)>=start&&v.slice(0,10)<=end);if(g.metric_key==="contacts")return data.leads.filter(l=>inRange(l.created_at)).length;if(g.metric_key==="appointments")return data.activities.filter(a=>a.activity_type==="meeting"&&inRange(a.occurred_at)).length;if(g.metric_key==="visits")return data.activities.filter(a=>a.activity_type==="property_visit"&&inRange(a.occurred_at)).length;if(g.metric_key==="closings")return closedHistory.filter(h=>inRange(h.changed_at)).length;if(g.metric_key==="revenue")return data.leads.filter(l=>isWonLead(l)&&inRange(closedHistory.filter(h=>h.lead_id===l.id).sort((a,b)=>new Date(b.changed_at).getTime()-new Date(a.changed_at).getTime())[0]?.changed_at)).reduce((sum,l)=>sum+(l.estimated_value||0),0);return 0};
 const progress=(actual:number,target:number)=>target>0?Math.min(100,Math.round(actual/target*100)):actual>0?100:0;
 const metricLabel=(key:string)=>label("metric",key);
 const countText=(n:number)=>new Intl.NumberFormat("es-BO",{maximumFractionDigits:0}).format(n);
 return <div className="space-y-6">
  <Heading title="Métricas y objetivos" sub="Entendé qué funciona, dónde se frenan tus oportunidades y qué necesita seguimiento."/>
  <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Stat label="Contactos en cartera" value={data.leads.length}/><Stat label="Leads activos" value={active}/><Stat label="Cierres logrados" value={won}/><Stat label="Conversión total a cierre" value={(data.leads.length?Math.round(won/data.leads.length*100):0)+"%"}/></div>
  <section className="rounded-2xl border border-slate-200 bg-white p-5 sm:p-6">
   <div className="flex flex-col gap-1 sm:flex-row sm:items-end sm:justify-between"><div><h3 className="text-lg font-semibold">Embudo comercial</h3><p className="mt-1 text-sm text-slate-500">Contactos → citas → visitas → negociaciones → cierres.</p></div><p className="text-xs text-slate-400">Personas únicas registradas por etapa</p></div>
   <div className="mt-6 space-y-4">{funnel.map((step,i)=>{const previous=i?funnel[i-1].count:step.count;const rate=i&&previous?Math.round(step.count/previous*100):i?0:100;const width=Math.max(step.count?3:0,Math.round(step.count/Math.max(1,...funnel.map(x=>x.count))*100));return <div key={step.name}><div className="mb-2 flex items-center justify-between gap-3"><span className="text-sm font-medium">{step.name}</span><div className="flex items-center gap-3"><span className="text-sm font-semibold">{countText(step.count)}</span><span className="w-14 text-right text-xs text-slate-500">{i?rate+"% conv.":"100%"}</span></div></div><div className="h-3 overflow-hidden rounded-full bg-slate-100"><div className="h-full rounded-full transition-all" style={{width:width+"%",background:step.color}}/></div>{i>0&&<p className="mt-1 text-xs text-slate-400">{previous>step.count?countText(previous-step.count)+" oportunidades menos que en la etapa anterior":"Comparado con la etapa anterior"}</p>}</div>})}</div>
   <p className="mt-4 rounded-xl bg-blue-50 px-4 py-3 text-xs leading-5 text-blue-800">El embudo combina la etapa actual de cada lead con su historial y las actividades de citas/visitas registradas. Un mismo lead puede aparecer en varias etapas que haya alcanzado.</p>
  </section>
  <div className="grid gap-5 xl:grid-cols-3">
   <section className="rounded-2xl border border-slate-200 bg-white p-5"><div className="flex items-center gap-2"><Clock3 size={18} className="text-blue-600"/><h3 className="font-semibold">Tiempo promedio de cierre</h3></div><p className="mt-5 text-3xl font-semibold">{averageCloseDays===null?"—":averageCloseDays+" días"}</p><p className="mt-2 text-sm text-slate-500">{closeDurations.length? "Calculado sobre "+closeDurations.length+" cierres con historial de etapa.":"Se calcula cuando un lead ganado tiene historial de cambio de etapa."}</p></section>
   <section className="rounded-2xl border border-slate-200 bg-white p-5"><div className="flex items-center gap-2"><AlertTriangle size={18} className="text-amber-600"/><h3 className="font-semibold">Leads sin seguimiento</h3></div><p className="mt-5 text-3xl font-semibold">{noFollowUp.length}</p><p className="mt-2 text-sm text-slate-500">Activos sin próxima fecha o con seguimiento vencido.</p>{noFollowUp.length>0&&<button onClick={()=>{const e=document.getElementById("metrics-unfollowed");e?.scrollIntoView({behavior:"smooth",block:"start"})}} className="mt-4 text-sm font-semibold text-blue-600">Ver oportunidades →</button>}</section>
   <section className="rounded-2xl border border-slate-200 bg-white p-5"><div className="flex items-center gap-2"><TrendingUp size={18} className="text-emerald-600"/><h3 className="font-semibold">Actividad registrada</h3></div><p className="mt-5 text-3xl font-semibold">{data.activities.length}</p><p className="mt-2 text-sm text-slate-500">Actividades recientes disponibles para análisis.</p><p className="mt-3 text-xs text-slate-400">Citas: {data.activities.filter(a=>a.activity_type==="meeting").length} · Visitas: {data.activities.filter(a=>a.activity_type==="property_visit").length}</p></section>
  </div>
  <section className="rounded-2xl border border-slate-200 bg-white p-5 sm:p-6"><h3 className="text-lg font-semibold">Rendimiento por fuente de captación</h3><p className="mt-1 text-sm text-slate-500">Compará cuántos contactos llegan por cada canal y cuántos terminan en cierre.</p><div className="mt-5 overflow-x-auto"><table className="w-full min-w-[520px] text-left text-sm"><thead className="bg-slate-50 text-xs uppercase text-slate-500"><tr><th className="px-3 py-3">Fuente</th><th className="px-3 py-3">Contactos</th><th className="px-3 py-3">Cierres</th><th className="px-3 py-3">Conversión</th></tr></thead><tbody className="divide-y divide-slate-100">{sources.map(s=><tr key={s.source}><td className="px-3 py-3 font-medium">{s.label}</td><td className="px-3 py-3">{s.total}</td><td className="px-3 py-3">{s.wins}</td><td className="px-3 py-3"><div className="flex items-center gap-2"><div className="h-2 w-20 overflow-hidden rounded-full bg-slate-100"><div className="h-full rounded-full bg-blue-600" style={{width:s.rate+"%"}}/></div><span>{s.rate}%</span></div></td></tr>)}</tbody></table>{!sources.length&&<Empty text="Cargá contactos y su fuente de captación para comparar canales."/>}</div></section>
  <section id="metrics-unfollowed" className="rounded-2xl border border-amber-200 bg-white p-5 sm:p-6"><div className="flex items-center gap-2"><AlertTriangle size={18} className="text-amber-600"/><h3 className="text-lg font-semibold">Oportunidades que necesitan seguimiento</h3></div><p className="mt-1 text-sm text-slate-500">Estos leads están activos, pero no tienen una próxima fecha de seguimiento vigente.</p><div className="mt-4 space-y-2">{noFollowUp.slice(0,10).map(l=><div key={l.id} className="flex flex-col gap-2 rounded-xl bg-amber-50/70 p-3 sm:flex-row sm:items-center sm:justify-between"><div className="min-w-0"><p className="font-medium">{l.name}</p><p className="mt-1 text-xs text-slate-500">{label("source",l.source)} · Último registro: {date(l.created_at)}</p></div><span className="self-start rounded-lg bg-white px-2.5 py-1 text-xs text-amber-700">{l.next_follow_up_at?"Seguimiento vencido":"Sin fecha próxima"}</span></div>)}{!noFollowUp.length&&<Empty text="¡Bien! Todos los leads activos tienen una fecha de seguimiento futura."/>}{noFollowUp.length>10&&<p className="text-xs text-slate-500">Mostrando 10 de {noFollowUp.length} oportunidades.</p>}</div></section>
  <div className="grid gap-5 xl:grid-cols-2">
   <section className="rounded-2xl border border-slate-200 bg-white p-5 sm:p-6"><div className="flex items-center justify-between gap-3"><div><h3 className="font-semibold">{editingGoalId?"Editar objetivo":"Objetivos configurables"}</h3><p className="mt-1 text-sm text-slate-500">Definí la meta y el período que querés medir.</p></div>{editingGoalId&&<button type="button" onClick={cancelEdit} className="text-sm text-slate-500 underline">Cancelar edición</button>}</div><form onSubmit={save} className="mt-5 space-y-4"><Field label="Métrica"><select className={input} value={form.metric_key} onChange={e=>setForm({...form,metric_key:e.target.value})}><option value="contacts">Contactos</option><option value="appointments">Citas</option><option value="visits">Visitas</option><option value="closings">Cierres</option><option value="revenue">Ingresos estimados</option></select></Field><div className="grid gap-3 sm:grid-cols-2"><Field label="Período"><select className={input} value={form.period} onChange={e=>setForm({...form,period:e.target.value})}><option value="daily">Diario</option><option value="weekly">Semanal</option><option value="monthly">Mensual</option></select></Field><Field label="Objetivo"><input type="number" min="0" step={form.metric_key==="revenue"?"0.01":"1"} required className={input} value={form.target_value} onChange={e=>setForm({...form,target_value:e.target.value})}/></Field></div><div className="grid gap-3 sm:grid-cols-2"><Field label="Desde"><input type="date" required className={input} value={form.starts_on} onChange={e=>setForm({...form,starts_on:e.target.value})}/></Field><Field label="Hasta"><input type="date" min={form.starts_on} className={input} value={form.ends_on} onChange={e=>setForm({...form,ends_on:e.target.value})}/></Field></div><button disabled={busy} className="rounded-xl bg-blue-600 px-4 py-3 text-sm font-semibold text-white disabled:opacity-60">{busy?(editingGoalId?"Actualizando…":"Guardando…"):(editingGoalId?"Guardar cambios":"Guardar objetivo")}</button></form></section>
   <section className="rounded-2xl border border-slate-200 bg-white p-5 sm:p-6"><h3 className="font-semibold">Objetivos guardados y resultados reales</h3><p className="mt-1 text-sm text-slate-500">Cada objetivo puede editarse o eliminarse. El avance usa los datos registrados.</p><div className="mt-5 space-y-3">{data.goals.map(g=>{const actual=goalActual(g);const pct=progress(actual,Number(g.target_value));return <div key={g.id} className="rounded-xl border border-slate-100 bg-slate-50 p-4"><div className="flex items-start justify-between gap-3"><div className="min-w-0"><p className="font-semibold">{metricLabel(g.metric_key)}</p><p className="mt-1 text-xs text-slate-500">{label("period",g.period)} · {g.starts_on}{g.ends_on?" a "+g.ends_on:" en adelante"}</p></div><div className="text-right"><p className="text-lg font-semibold text-blue-700">{countText(actual)} <span className="text-xs font-normal text-slate-500">/ {countText(Number(g.target_value))}</span></p><p className="text-xs text-slate-500">{pct}% cumplido</p></div></div><div className="mt-3 h-2 overflow-hidden rounded-full bg-slate-200"><div className="h-full rounded-full bg-blue-600" style={{width:pct+"%"}}/></div><div className="mt-3 flex flex-wrap gap-2"><button type="button" onClick={()=>editGoal(g)} className="inline-flex items-center gap-1.5 rounded-lg border border-slate-200 bg-white px-3 py-2 text-xs font-medium"><Pencil size={13}/>Editar</button><button type="button" onClick={()=>deleteGoal(g.id)} className="inline-flex items-center gap-1.5 rounded-lg border border-rose-200 bg-white px-3 py-2 text-xs font-medium text-rose-600"><Trash2 size={13}/>Eliminar</button></div></div>})}{!data.goals.length&&<Empty text="Todavía no configuraste objetivos."/>}</div></section>
  </div>
 </div>
}
function Settings({stages,add,reload,email,fields,customForm,setCustomForm,createField,busy}:{stages:Stage[];add:()=>void;reload:()=>void;email:string;fields:CustomField[];customForm:{entity_type:string;name:string;field_key:string;field_type:string;options:string;is_required:boolean};setCustomForm:(v:typeof customForm)=>void;createField:(e:React.FormEvent<HTMLFormElement>)=>void;busy:boolean}) {
  return (
    <div className="space-y-5">
      <Heading title="Configuración" sub="Preferencias, etapas y campos personalizados." />
      <section className="rounded-2xl border border-slate-200 bg-white p-5">
        <h3 className="font-semibold">Cuenta autorizada</h3>
        <div className="mt-4 flex items-center gap-3 rounded-xl bg-slate-50 p-4">
          <LockKeyhole className="text-blue-600" />
          <div><p className="text-sm font-medium">{email}</p><p className="mt-1 text-xs text-emerald-600">Sesión autenticada</p></div>
        </div>
      </section>
      <section className="rounded-2xl border border-slate-200 bg-white p-5">
        <div className="flex items-center justify-between gap-3">
          <div><h3 className="font-semibold">Etapas del pipeline</h3><p className="mt-1 text-sm text-slate-500">Agregá etapas según tu proceso comercial.</p></div>
          <button type="button" onClick={add} className="inline-flex items-center gap-2 rounded-xl bg-blue-600 px-4 py-2.5 text-sm text-white"><Plus size={16}/>Agregar etapa</button>
        </div>
        <div className="mt-5 space-y-2">
          {stages.map(s => <div key={s.id} className="flex items-center gap-3 rounded-xl border border-slate-100 p-3"><span className="size-3 rounded-full" style={{background:s.color}}/><span className="flex-1 text-sm font-medium">{s.name}</span>{s.is_won && <span className="text-xs text-emerald-600">Ganado</span>}{s.is_lost && <span className="text-xs text-rose-600">Perdido</span>}</div>)}
          {!stages.length && <Empty text="Ejecutá la migración SQL para configurar etapas."/>}
        </div>
      </section>
      <section className="rounded-2xl border border-slate-200 bg-white p-5">
        <h3 className="font-semibold">Campos personalizados</h3>
        <p className="mt-1 text-sm text-slate-500">Creá datos extra para organizar tus leads o propiedades.</p>
        <form onSubmit={createField} className="mt-4 grid gap-3 sm:grid-cols-2">
          <Field label="Aplicar a"><select className={input} value={customForm.entity_type} onChange={e=>setCustomForm({...customForm,entity_type:e.target.value})}><option value="lead">Clientes y leads</option><option value="property">Propiedades</option></select></Field>
          <Field label="Nombre" required><input required className={input} value={customForm.name} onChange={e=>setCustomForm({...customForm,name:e.target.value})} placeholder="Ej. Zona de interés"/></Field>
          <Field label="Identificador" required><input required pattern="[a-z][a-z0-9_]*" className={input} value={customForm.field_key} onChange={e=>setCustomForm({...customForm,field_key:e.target.value.toLowerCase().replace(/[^a-z0-9_]/g,"_")})} placeholder="zona_interes"/></Field>
          <Field label="Tipo de dato"><select className={input} value={customForm.field_type} onChange={e=>setCustomForm({...customForm,field_type:e.target.value})}><option value="text">Texto corto</option><option value="textarea">Texto largo</option><option value="number">Número</option><option value="date">Fecha</option><option value="boolean">Sí / No</option><option value="select">Lista de opciones</option></select></Field>
          {customForm.field_type === "select" && <Field label="Opciones separadas por coma"><input className={input} value={customForm.options} onChange={e=>setCustomForm({...customForm,options:e.target.value})} placeholder="Calacoto, San Miguel, Achumani"/></Field>}
          <label className="flex items-center gap-2 text-sm text-slate-700"><input type="checkbox" checked={customForm.is_required} onChange={e=>setCustomForm({...customForm,is_required:e.target.checked})}/>Obligatorio</label>
          <div className="sm:col-span-2"><button disabled={busy} className="rounded-xl bg-blue-600 px-4 py-2.5 text-sm font-semibold text-white disabled:opacity-60">{busy ? "Guardando…" : "Crear campo"}</button></div>
        </form>
        <div className="mt-5 border-t border-slate-100 pt-4">
          <h4 className="text-sm font-semibold">Campos existentes</h4>
          {fields.map(f => <div key={f.id} className="mt-2 flex items-center gap-2 rounded-lg bg-slate-50 p-3 text-sm"><span className="flex-1">{f.name} <code className="text-xs text-slate-400">{f.field_key}</code></span><span className="text-xs text-slate-500">{f.entity_type === "lead" ? "Lead" : "Propiedad"} · {f.field_type}</span></div>)}
          {!fields.length && <p className="mt-3 text-sm text-slate-400">Todavía no hay campos personalizados.</p>}
        </div>
      </section>
      <button type="button" onClick={reload} className="rounded-xl border border-slate-200 bg-white px-4 py-2.5 text-sm">Actualizar datos</button>
    </div>
  );
}

function LeadPanel({lead,stages,close,move,remove,refresh,notice}:{lead:Lead;stages:Stage[];close:()=>void;move:(l:Lead,s:string)=>void;remove:(l:Lead)=>void;refresh:()=>void;notice:(s:string)=>void}){const [note,setNote]=useState("");const [follow,setFollow]=useState(lead.next_follow_up_at?lead.next_follow_up_at.slice(0,10):"");const [busy,setBusy]=useState(false);async function addNote(e:React.FormEvent<HTMLFormElement>){e.preventDefault();setBusy(true);const sb=createClient();const {error}=await sb.from("activities").insert({lead_id:lead.id,activity_type:"note",subject:"Nota de seguimiento",notes:note});if(error)notice(error.message);else{setNote("");await refresh()}setBusy(false)}async function saveFollow(e:React.FormEvent<HTMLFormElement>){e.preventDefault();setBusy(true);const sb=createClient();const {error}=await sb.from("leads").update({next_follow_up_at:follow||null,updated_at:new Date().toISOString()}).eq("id",lead.id);if(error)notice(error.message);else{if(follow)await sb.from("tasks").insert({title:"Seguimiento: "+lead.name,due_at:follow+"T09:00:00",lead_id:lead.id,priority:"normal"});notice("Seguimiento guardado.");await refresh()}setBusy(false)}return <div className="fixed inset-0 z-40 flex justify-end bg-slate-950/35" onMouseDown={e=>{if(e.target===e.currentTarget)close()}}><aside className="h-full w-full max-w-xl overflow-y-auto bg-white shadow-2xl"><div className="sticky top-0 flex items-center justify-between border-b bg-white/95 px-6 py-5"><div><p className="text-xs text-slate-400">Ficha de cliente</p><h2 className="mt-1 text-xl font-semibold">{lead.name}</h2></div><button onClick={close} className="rounded-lg p-2 text-slate-400"><X/></button></div><div className="space-y-6 p-6"><div className="flex flex-wrap gap-2"><span className="rounded-full bg-blue-50 px-3 py-1.5 text-xs text-blue-700">{label("type",lead.lead_type)}</span><span className="rounded-full bg-slate-100 px-3 py-1.5 text-xs">{label("source",lead.source)}</span></div><Field label="Etapa"><select className={input} value={lead.stage_id||""} onChange={e=>move(lead,e.target.value)}><option value="">Sin etapa</option>{stages.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select></Field><div className="grid grid-cols-2 gap-3"><Stat label="Valor estimado" value={lead.estimated_value?money(lead.estimated_value):"Sin definir"}/><Stat label="Fecha de alta" value={date(lead.created_at)}/></div><form onSubmit={saveFollow} className="space-y-3 rounded-2xl border p-4"><h3 className="text-sm font-semibold">Próximo seguimiento</h3><Field label="Fecha"><input type="date" value={follow} onChange={e=>setFollow(e.target.value)} className={input}/></Field><button disabled={busy} className="rounded-xl bg-blue-600 px-4 py-2.5 text-sm font-semibold text-white">Guardar seguimiento</button></form><form onSubmit={addNote} className="space-y-3 rounded-2xl border p-4"><h3 className="text-sm font-semibold">Registrar nota</h3><textarea required rows={4} value={note} onChange={e=>setNote(e.target.value)} className={input} placeholder="¿Qué conversaron? ¿Cuál es el próximo paso?"/><button disabled={busy} className="rounded-xl bg-blue-600 px-4 py-2.5 text-sm font-semibold text-white">Agregar al historial</button></form><button onClick={()=>remove(lead)} className="rounded-xl border border-rose-200 px-4 py-2.5 text-sm text-rose-600">Eliminar cliente</button></div></aside></div>}
